class Account {
  private balance = 0;
  private overdraftLimit = 100;
  getBalance() { return this.balance; }
  getOverdraftLimit() { return this.overdraftLimit; }
}

class AuditService {
  record(account: Account) {
    const b = account.getBalance();
    const allowed = b + account.getOverdraftLimit();
    console.log(allowed);
  }
}

